use std::io::{self, Write};

pub struct Editor {
    should_quit: bool,
}

impl Editor {
    pub fn new() -> Self {
        Editor { should_quit: false }
    }

    pub fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        crossterm::terminal::enable_raw_mode()?;
        io::stdout().write_all(crossterm::cursor::Hide::to_string().as_bytes())?;
        io::stdout().write_all(crossterm::terminal::Clear(crossterm::terminal::ClearType::All).to_string().as_bytes())?;
        loop {
            self.refresh_screen()?;
            if self.should_quit {
                break;
            }
            let mut buf = [0u8; 1];
            io::stdin().read_exact(&mut buf)?;
            self.process_keypress(buf[0]);
        }
        io::stdout().write_all(crossterm::cursor::Show::to_string().as_bytes())?;
        crossterm::terminal::disable_raw_mode()?;
        Ok(())
    }

    fn process_keypress(&mut self, key: u8) {
        match key {
            0x11 => self.should_quit = true,
            _ => {}
        }
    }

    fn refresh_screen(&self) -> Result<(), Box<dyn std::error::Error>> {
        let mut stdout = io::stdout();
        stdout.write_all(b"~\\
")?;
        if self.should_quit {
            write!(stdout, crossterm::cursor::MoveTo(0, 0))?;
        }
        stdout.flush()?;
        Ok(())
    }
}

