use std::fs;
use std::io::{self, Read, Write};

pub struct Cursor {
    pub x: usize,
    pub y: usize,
}

pub struct Editor {
    should_quit: bool,
    cursor: Cursor,
    rows: Vec<String>,
    filename: Option<String>,
    status_msg: String,
    dirty: bool,
}

impl Editor {
    pub fn new(filename: Option<String>) -> Self {
        let rows = match &filename {
            Some(f) => fs::read_to_string(f)
                .map(|s| {
                    let mut lines: Vec<String> = s.lines().map(String::from).collect();
                    if lines.is_empty() { lines.push(String::new()); }
                    lines
                })
                .unwrap_or_else(|_| vec![String::new()]),
            None => vec![String::new()],
        };
        Editor {
            should_quit: false,
            cursor: Cursor { x: 0, y: 0 },
            rows,
            filename,
            status_msg: String::new(),
            dirty: false,
        }
    }

    pub fn save(&mut self) {
        let filename = self.filename.clone().unwrap_or_else(|| "untitled".to_string());
        let content: String = self.rows.join("\
");
        match fs::write(&filename, &content) {
            Ok(_) => {
                self.dirty = false;
                self.status_msg = format!("Saved to {} ({} bytes)", filename, content.len());
            }
            Err(e) => {
                self.status_msg = format!("Error saving: {}", e);
            }
        }
    }

    fn insert_char(&mut self, c: char) {
        if self.rows.is_empty() { self.rows.push(String::new()); }
        let row = &mut self.rows[self.cursor.y];
        row.insert(self.cursor.x, c);
        self.cursor.x += 1;
        self.dirty = true;
    }

    fn delete_char(&mut self) {
        if self.cursor.x > 0 {
            let row = &mut self.rows[self.cursor.y];
            row.remove(self.cursor.x - 1);
            self.cursor.x -= 1;
            self.dirty = true;
        } else if self.cursor.y > 0 {
            let current_row = self.rows.remove(self.cursor.y);
            self.cursor.y -= 1;
            self.cursor.x = self.rows[self.cursor.y].len();
            self.rows[self.cursor.y].push_str(&current_row);
            self.dirty = true;
        }
    }

    fn insert_newline(&mut self) {
        let remainder = self.rows[self.cursor.y][self.cursor.x..].to_string();
        self.rows[self.cursor.y].truncate(self.cursor.x);
        self.cursor.y += 1;
        self.cursor.x = 0;
        self.rows.insert(self.cursor.y, remainder);
        self.dirty = true;
    }

    fn move_cursor(&mut self, key: u8) {
        match key {
            0x41 => { if self.cursor.y > 0 { self.cursor.y -= 1; } }
            0x42 => { let last = self.rows.len().saturating_sub(1); if self.cursor.y < last { self.cursor.y += 1; } }
            0x44 => { if self.cursor.x > 0 { self.cursor.x -= 1; } else if self.cursor.y > 0 { self.cursor.y -= 1; self.cursor.x = self.rows[self.cursor.y].len(); } }
            0x43 => { let row_len = self.rows[self.cursor.y].len(); if self.cursor.x < row_len { self.cursor.x += 1; } else { self.cursor.y += 1; self.cursor.x = 0; } }
            0x48 => { self.cursor.x = 0; }
            0x46 => { self.cursor.x = self.rows[self.cursor.y].len(); }
            _ => {}
        }
        let row_len = self.rows.get(self.cursor.y).map_or(0, |r| r.len());
        if self.cursor.x > row_len { self.cursor.x = row_len; }
    }

    pub fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        crossterm::terminal::enable_raw_mode()?;
        loop {
            if self.should_quit { break; }
            let mut buf = [0u8; 1];
            io::stdin().read_exact(&mut buf)?;
            match buf[0] {
                0x11 => self.should_quit = true,
                0x13 => self.save(),
                0x0D => self.insert_newline(),
                0x7F | 0x08 => self.delete_char(),
                0x1B => {
                    let mut seq = [0u8; 2];
                    io::stdin().read_exact(&mut seq)?;
                    if seq[0] == 0x5B { self.move_cursor(seq[1]); }
                }
                c if !c.is_control() => self.insert_char(c as char),
                _ => {}
            }
        }
        crossterm::terminal::disable_raw_mode()?;
        Ok(())
    }
}

