pub enum SyntaxType {
    Number,
    Keyword,
    String,
    Normal,
}

const KEYWORDS: &[&str] = &["if", "else", "while", "fn", "let", "mut", "pub", "struct", "impl", "return", "use", "mod", "match", "self", "true", "false"];

pub fn highlight_line(line: &str) -> Vec<(SyntaxType, String)> {
    let mut segments = Vec::new();
    let mut chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        // String literal
        if chars[i] == '"' {
            let start = i;
            i += 1;
            while i < chars.len() && chars[i] != '"' {
                if chars[i] == '\\' { i += 1; }
                i += 1;
            }
            if i < chars.len() { i += 1; }
            segments.push((SyntaxType::String, chars[start..i].iter().collect()));
            continue;
        }
        // Number
        if chars[i].is_ascii_digit() {
            let start = i;
            while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '_') {
                i += 1;
            }
            segments.push((SyntaxType::Number, chars[start..i].iter().collect()));
            continue;
        }
        // Identifier / keyword
        if chars[i].is_alphabetic() || chars[i] == '_' {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            let stype = if KEYWORDS.contains(&word.as_str()) {
                SyntaxType::Keyword
            } else {
                SyntaxType::Normal
            };
            segments.push((stype, word));
            continue;
        }
        // Other characters
        segments.push((SyntaxType::Normal, chars[i].to_string()));
        i += 1;
    }
    segments
}

pub fn to_ansi_segment(syntax_type: &SyntaxType, text: &str) -> String {
    match syntax_type {
        SyntaxType::Number => format!("\x1b[33m{}\x1b[0m", text),
        SyntaxType::Keyword => format!("\x1b[36m{}\x1b[0m", text),
        SyntaxType::String => format!("\x1b[32m{}\x1b[0m", text),
        SyntaxType::Normal => text.to_string(),
    }
}
